<script setup lang="ts">import type{DataRow,PageConfig}from'~/types/platform';defineProps<{page:PageConfig;routePath:string}>();const{showToast}=useToast();const data=ref<DataRow[]>([]);const debit=computed(()=>data.value.reduce((s,r)=>s+Number(r.debit||0),0));const credit=computed(()=>data.value.reduce((s,r)=>s+Number(r.credit||0),0));const money=(n:number)=>`Rp ${n.toLocaleString('en-US')}`</script>
<template><PageActions primary-label="Post Journal" @create="showToast(debit===credit?'Journal is balanced and ready to post.':`Journal is not balanced.`)" @import="showToast('Import wizard ready.')" @export="showToast('Journal export prepared.')" @filter="showToast('Use grid filters below.')" @refresh="showToast('Journal refreshed.')" @more="showToast('More actions.')"/><section class="platform-kpis"><article v-for="metric in [['Total Debit',money(debit)],['Total Credit',money(credit)],['Difference',money(Math.abs(debit-credit))],['Status',debit===credit?'Balanced':'Unbalanced']]" :key="metric[0]" class="platform-kpi"><span class="platform-kpi-icon blue"><AppIcon name="file"/></span><div><small>{{metric[0]}}</small><strong>{{metric[1]}}</strong><p>Calculated automatically</p></div></article></section><DataGridSection :page="page" :route-path="routePath" @loaded="data=$event"/></template>
